class Solution:
    def twoSum(self, numbers: list[int], target: int) -> list[int]:
        l, r = 0, len(numbers) - 1
        while l < r:
            total = numbers[l] + numbers[r]  # viz:sum
            if total == target:
                return [l + 1, r + 1]  # viz:found
            if total < target:
                l += 1  # viz:move_l
            else:
                r -= 1  # viz:move_r
        return []
